inline bool Same(const WorldText::Vec3& a,const WorldText::Vec3& b){return a.x==b.x&&a.y==b.y&&a.z==b.z;}
inline double Cross(const WorldText::Vec3& a,const WorldText::Vec3& b,const WorldText::Vec3& p){return (double(b.x)-a.x)*(double(p.z)-a.z)-(double(b.z)-a.z)*(double(p.x)-a.x);}
inline double TwiceArea(const WorldText::Vec3* p,unsigned int count){double result=0;for(unsigned int i=1;i+1<count;i++)result-=Cross(p[0],p[i],p[i+1]);return result;}
inline bool Separated(const WorldText::Vec3* a,unsigned int ac,const WorldText::Vec3* b,unsigned int bc){for(unsigned int i=0;i<ac;i++){bool outside=true;for(unsigned int j=0;j<bc;j++)if(Cross(a[i],a[(i+1)%ac],b[j])<0){outside=false;break;}if(outside)return true;}return false;}
inline bool InteriorsOverlap(const WorldText::Vec3* a,unsigned int ac,const WorldText::Vec3* b,unsigned int bc){return !Separated(a,ac,b,bc)&&!Separated(b,bc,a,ac);}
inline bool SharedSegment(const WorldText::Vec3& a,const WorldText::Vec3& b,const WorldText::Vec3& c,const WorldText::Vec3& d){
 if(Cross(a,b,c)!=0||Cross(a,b,d)!=0)return false;
 double dx=double(b.x)-a.x,dz=double(b.z)-a.z,length=dx*dx+dz*dz;
 double first=(double(c.x)-a.x)*dx+(double(c.z)-a.z)*dz,second=(double(d.x)-a.x)*dx+(double(d.z)-a.z)*dz;
 if(first>second){double swap=first;first=second;second=swap;}
 return second>0&&first<length&&first<second;
}
inline bool Adjacent(const SourcePoly& a,const SourcePoly& b){for(unsigned int i=0;i<a.count;i++)for(unsigned int j=0;j<b.count;j++)if(SharedSegment(a.vertices[i],a.vertices[(i+1)%a.count],b.vertices[j],b.vertices[(j+1)%b.count]))return true;return false;}
inline bool VertexKey(const unsigned char* data,const WorldText::Vec3* vertices,unsigned int count,unsigned int& key){if(!FiniteVector(data))return false;for(unsigned int i=0;i<count;i++)if(VectorEqual(data,vertices[i])){key=i;return true;}return false;}
inline Point Normalized(const WorldText::Vec3& p,const WorldText::Vec3& low,double width,double depth){Point value={(double(p.x)-low.x)/width,(double(p.z)-low.z)/depth};return value;}
struct Segment {WorldText::Vec3 a,b;};
inline double Axis(const WorldText::Vec3& p,bool useX){return useX?p.x:p.z;}
inline bool Collinear(const Segment& a,const Segment& b){return Cross(a.a,a.b,b.a)==0&&Cross(a.a,a.b,b.b)==0;}
inline bool Covers(const Segment& edge,bool useX,double midpoint){double a=Axis(edge.a,useX),b=Axis(edge.b,useX);return (a<midpoint&&midpoint<b)||(b<midpoint&&midpoint<a);}
// Exact source-integer interval decomposition supplements floating clipping.
// It prevents a tiny missing/outside sliver from being hidden by its tolerance.
// The midpoint is an integer or half-integer on the segment's dominant axis.
inline bool Boundary(const Segment* source,unsigned int sourceCount,const Segment* border,unsigned int borderCount,double* splits){
 for(unsigned int family=0;family<2;family++)for(unsigned int i=0;i<(family?borderCount:sourceCount);i++){
  const Segment& current=family?border[i]:source[i];bool useX=Abs(double(current.b.x)-current.a.x)>=Abs(double(current.b.z)-current.a.z);double low=Axis(current.a,useX),high=Axis(current.b,useX);if(low>high){double swap=low;low=high;high=swap;}unsigned int count=0;splits[count++]=low;splits[count++]=high;
  for(unsigned int group=0;group<2;group++)for(unsigned int j=0;j<(group?borderCount:sourceCount);j++){const Segment& other=group?border[j]:source[j];if(!Collinear(current,other))continue;double a=Axis(other.a,useX),b=Axis(other.b,useX);if(a>low&&a<high)splits[count++]=a;if(b>low&&b<high)splits[count++]=b;}
  for(unsigned int j=1;j<count;j++){double value=splits[j];unsigned int k=j;while(k&&splits[k-1]>value){splits[k]=splits[k-1];k--;}splits[k]=value;}
  for(unsigned int j=1;j<count;j++)if(splits[j]>splits[j-1]){double midpoint=(splits[j]+splits[j-1])*.5;unsigned int sourceHits=0,borderHits=0;for(unsigned int k=0;k<sourceCount;k++)if(Collinear(current,source[k])&&Covers(source[k],useX,midpoint))sourceHits++;for(unsigned int k=0;k<borderCount;k++)if(Collinear(current,border[k])&&Covers(border[k],useX,midpoint))borderHits++;if(family){if(sourceHits!=1||borderHits!=1)return false;}else if(sourceHits<1||sourceHits>2||borderHits!=(sourceHits==1?1u:0u))return false;}
 }
 return true;
}
